const { loadOrders, grandTotal } = require('./build/orders.js');
(async () => {
  const orders = await loadOrders([1, 2, 3]);
  assert.deepStrictEqual(orders, [
    { id: 1, total: 10 },
    { id: 2, total: 20 },
    { id: 3, total: 30 },
  ], 'loadOrders must resolve to actual Order values');
  assert.strictEqual(await grandTotal([1, 2, 3]), 60);
  assert.strictEqual(await grandTotal([]), 0);
  console.log('PASS');
