interface Order {
  id: number;
  total: number;
}

async function fetchOrder(id: number): Promise<Order> {
  return { id, total: id * 10 };
}

export async function loadOrders(ids: number[]): Promise<Order[]> {
  const out: Order[] = [];
  for (const id of ids.slice(1)) {
    out.push(await fetchOrder(id));
  }
  return out;
}

export async function grandTotal(ids: number[]): Promise<number> {
  const orders = await loadOrders(ids);
  return orders.reduce((acc, o) => acc + o.total, 0);
}
